<?php require __DIR__.'/../middleware.php';api_method('GET');$limit=max(1,min(50,(int)($_GET['limit']??20)));$offset=max(0,(int)($_GET['offset']??0));$q=db()->prepare("SELECT id,title,slug,location,employment_type,summary,closing_date,published_at FROM jobs WHERE status='published' AND (closing_date IS NULL OR closing_date>=CURDATE()) ORDER BY is_featured DESC,published_at DESC LIMIT ? OFFSET ?");$q->bindValue(1,$limit,PDO::PARAM_INT);$q->bindValue(2,$offset,PDO::PARAM_INT);$q->execute();api_json(['ok'=>true,'data'=>$q->fetchAll(),'pagination'=>['limit'=>$limit,'offset'=>$offset]]);